import { AsyncLocalStorage } from 'node:async_hooks';
const als = new AsyncLocalStorage<string>();
function rec(tag: string): void { console.log(tag + '=' + String(als.getStore())); }
function sleep(ms: number): Promise<number> { return new Promise<number>((r: (v: number) => void): void => { setTimeout((): void => { r(ms); }, ms); }); }
async function main(): Promise<void> {
  await als.run('B', async (): Promise<void> => {
    await sleep(1);
    queueMicrotask((): void => { rec('microtask-after-await'); });
    await sleep(1);
    await Promise.resolve(1).then((): void => { rec('then-after-await'); });
    await Promise.reject(new Error('x')).catch((): void => { rec('catch-after-await'); });
    await Promise.resolve(1).finally((): void => { rec('finally-after-await'); });
    await Promise.resolve(1).then((): void => { rec('then-after-await2'); });
    rec('end');
  });
  rec('outside');
}
